package huawei

import (
	"errors"
	"strconv"
	"strings"

	modbusreg "github.com/Project-Helianthus/helianthus-modbusreg"
)

// GridCodeAccess is the catalogue access token of one grid-code row.
type GridCodeAccess string

const (
	// GridCodeAccessReadOnly is the catalogue token RO.
	GridCodeAccessReadOnly GridCodeAccess = "RO"
	// GridCodeAccessReadWrite is the catalogue token RW.
	GridCodeAccessReadWrite GridCodeAccess = "RW"
	// GridCodeAccessWriteOnly is the catalogue token WO.
	GridCodeAccessWriteOnly GridCodeAccess = "WO"
)

// GridCodeSetting is one catalogue grid-code or grid-support row.
// It has no SemReg element. The methods return register words for a hand
// call in the modbusreg namespace and do not send them.
type GridCodeSetting struct {
	// Card is the catalogue card that declares the row.
	Card string
	// Key is the catalogue key.
	Key string
	// Address is the holding-register address.
	Address uint16
	// Quantity is the register count on the card.
	Quantity uint16
	// Type is the catalogue wire type.
	Type string
	// Gain is the catalogue gain token, unapplied.
	Gain string
	// Unit is the catalogue unit token.
	Unit string
	// Access is the catalogue access token.
	Access GridCodeAccess
	// Occurrence distinguishes catalogue rows that share a key and address.
	// Zero means the card omits it.
	Occurrence uint16
	// RegisterAddressed reports that the card states no name or role, so the
	// row is addressed by register and type.
	RegisterAddressed bool
}

// CallName returns the catalogue key when the card names the row, and an
// empty name when the row is addressed by register and type.
func (row GridCodeSetting) CallName() string {
	if row.RegisterAddressed {
		return ""
	}
	return row.Key
}

// IntegerGain returns the gain when the catalogue token is one positive integer.
func (row GridCodeSetting) IntegerGain() (int, bool) {
	value, err := strconv.Atoi(row.Gain)
	if err != nil || value <= 0 || strconv.Itoa(value) != row.Gain {
		return 0, false
	}
	return value, true
}

// Readable reports whether the access token admits a read and the type and
// quantity agree.
func (row GridCodeSetting) Readable() bool {
	if row.shape() == gridCodeShapeOpen {
		return false
	}
	return row.Access == GridCodeAccessReadOnly || row.Access == GridCodeAccessReadWrite
}

// Writable reports whether the access token admits a write and the type and
// quantity agree.
func (row GridCodeSetting) Writable() bool {
	if row.shape() == gridCodeShapeOpen {
		return false
	}
	return row.Access == GridCodeAccessReadWrite || row.Access == GridCodeAccessWriteOnly
}

// ReadSpan returns the holding-register function, address and quantity of a
// readable row.
func (row GridCodeSetting) ReadSpan() (uint8, uint16, uint16, error) {
	if !row.Readable() {
		return 0, 0, 0, errors.New("grid-code row is not readable")
	}
	return uint8(modbusreg.FunctionReadHoldingRegisters), row.Address, row.Quantity, nil
}

// EncodeWrite encodes a register integer as the card's scalar words.
// A rejected value returns no words.
func (row GridCodeSetting) EncodeWrite(native int64) ([]uint16, error) {
	if !row.Writable() || row.shape() != gridCodeShapeScalar {
		return nil, errors.New("grid-code row has no scalar write")
	}
	return gridCodePutInteger(row.Type, row.Quantity, native)
}

// DecodeRead returns the register integer of a scalar read of this row.
func (row GridCodeSetting) DecodeRead(words []uint16) (int64, error) {
	if !row.Readable() || row.shape() != gridCodeShapeScalar {
		return 0, errors.New("grid-code row has no scalar read")
	}
	if len(words) != int(row.Quantity) {
		return 0, errors.New("grid-code read width disagrees with the card")
	}
	return gridCodeTakeInteger(row.Type, words)
}

// EncodeBlock copies a raw block of exactly the card's quantity.
// A rejected block returns no words.
func (row GridCodeSetting) EncodeBlock(words []uint16) ([]uint16, error) {
	if !row.Writable() || row.shape() != gridCodeShapeBlock {
		return nil, errors.New("grid-code row has no block write")
	}
	if len(words) != int(row.Quantity) {
		return nil, errors.New("grid-code block width disagrees with the card")
	}
	return gridCodeCopyWords(words), nil
}

// DecodeBlock copies a raw block of exactly the card's quantity.
func (row GridCodeSetting) DecodeBlock(words []uint16) ([]uint16, error) {
	if !row.Readable() || row.shape() != gridCodeShapeBlock {
		return nil, errors.New("grid-code row has no block read")
	}
	if len(words) != int(row.Quantity) {
		return nil, errors.New("grid-code block width disagrees with the card")
	}
	return gridCodeCopyWords(words), nil
}

// GridCodeSettings returns every grid-code and grid-support row, in listed order.
func GridCodeSettings() []GridCodeSetting {
	return gridCodeTable()
}

// GridCodeSettingsForRegister returns the rows of one card at one address and
// wire type, in listed order.
func GridCodeSettingsForRegister(card string, address uint16, wire string) []GridCodeSetting {
	var found []GridCodeSetting
	for _, row := range gridCodeTable() {
		if row.Card == card && row.Address == address && row.Type == wire {
			found = append(found, row)
		}
	}
	return found
}

const (
	gridCodeShapeOpen = iota
	gridCodeShapeScalar
	gridCodeShapeBlock
)

func (row GridCodeSetting) shape() int {
	switch row.Type {
	case "MLD", "BYTES":
		if row.Quantity > 0 {
			return gridCodeShapeBlock
		}
		return gridCodeShapeOpen
	}
	if _, _, err := gridCodeWidth(row.Type, row.Quantity); err != nil {
		return gridCodeShapeOpen
	}
	return gridCodeShapeScalar
}

func gridCodeTable() []GridCodeSetting {
	out := make([]GridCodeSetting, len(gridCodeRows))
	copy(out, gridCodeRows)
	return out
}

func init() {
	gridCodeRows = gridCodeParse(gridCodePacked)
}

var gridCodeRows []GridCodeSetting

func gridCodeParse(packed string) []GridCodeSetting {
	records := strings.Split(packed, ";")
	rows := make([]GridCodeSetting, 0, len(records))
	for _, record := range records {
		if record == "" {
			panic("grid-code record is empty")
		}
		rows = append(rows, gridCodeParseRecord(record))
	}
	if len(rows) == 0 {
		panic("grid-code table is empty")
	}
	return rows
}

func gridCodeParseRecord(record string) GridCodeSetting {
	fields := strings.Split(record, ",")
	if len(fields) != 10 {
		panic("grid-code record width")
	}
	access := GridCodeAccess(fields[7])
	switch access {
	case GridCodeAccessReadOnly, GridCodeAccessReadWrite, GridCodeAccessWriteOnly:
	default:
		panic("grid-code access")
	}
	if fields[9] != "0" && fields[9] != "1" {
		panic("grid-code name flag")
	}
	return GridCodeSetting{
		Card:              fields[0],
		Key:               fields[1],
		Address:           gridCodeNumber(fields[2]),
		Quantity:          gridCodeNumber(fields[3]),
		Type:              fields[4],
		Gain:              fields[5],
		Unit:              fields[6],
		Access:            access,
		Occurrence:        gridCodeNumber(fields[8]),
		RegisterAddressed: fields[9] == "1",
	}
}

func gridCodeNumber(field string) uint16 {
	number, err := strconv.ParseUint(field, 10, 16)
	if err != nil {
		panic("grid-code number")
	}
	return uint16(number)
}

func gridCodeWidth(wire string, quantity uint16) (int, bool, error) {
	switch wire {
	case "U16", "E16", "ENUM16":
		if quantity == 1 {
			return 16, false, nil
		}
	case "I16":
		if quantity == 1 {
			return 16, true, nil
		}
	case "U32":
		if quantity == 2 {
			return 32, false, nil
		}
	case "I32":
		if quantity == 2 {
			return 32, true, nil
		}
	}
	return 0, false, errors.New("grid-code type and quantity disagree")
}

func gridCodeInRange(bits int, signed bool, native int64) bool {
	if bits <= 0 || bits >= 63 {
		return false
	}
	if signed {
		limit := int64(1) << (bits - 1)
		return native >= -limit && native <= limit-1
	}
	return native >= 0 && uint64(native) <= (uint64(1)<<uint(bits))-1
}

func gridCodePutInteger(wire string, quantity uint16, native int64) ([]uint16, error) {
	bits, signed, err := gridCodeWidth(wire, quantity)
	if err != nil {
		return nil, err
	}
	if !gridCodeInRange(bits, signed, native) {
		return nil, errors.New("grid-code value is outside the card type")
	}
	words := make([]uint16, quantity)
	rest := uint64(native)
	for index := int(quantity) - 1; index >= 0; index-- {
		words[index] = uint16(rest)
		rest >>= 16
	}
	return words, nil
}

func gridCodeTakeInteger(wire string, words []uint16) (int64, error) {
	bits, signed, err := gridCodeWidth(wire, uint16(len(words)))
	if err != nil {
		return 0, err
	}
	var value uint64
	for _, word := range words {
		value = value<<16 | uint64(word)
	}
	if signed && value&(uint64(1)<<uint(bits-1)) != 0 {
		value |= ^uint64(0) << uint(bits)
	}
	return int64(value), nil
}

func gridCodeCopyWords(words []uint16) []uint16 {
	out := make([]uint16, len(words))
	copy(out, words)
	return out
}

